1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import type { SftpServer } from "../lib/sftp";
4	import { decryptSecret } from "../lib/crypto-box";
5	import {
6	  withServerSsh,
7	  exec,
8	  execInput,
9	  assertIdent,
10	  assert,
11	  assertInertSecret,
12	  why,
13	  shellQuote,
14	  pkgInstallPrefix,
15	  SETUP_TIMEOUT_MS,
16	  INSTALL_TIMEOUT_MS,
17	  QUICK_TIMEOUT_MS,
18	} from "../lib/ssh-exec";
19	import type { Job } from "@prisma/client";
20	import type { Client } from "ssh2";
21	
22	/**
23	 * Control-panel DB_CREATE / DB_DELETE handlers (MySQL/MariaDB & PostgreSQL).
24	 *
25	 * Registered in worker/index.ts:
26	 *   DB_CREATE: dbCreate,
27	 *   DB_DELETE: dbDelete,
28	 *
29	 * The generated DB password is decrypted IN MEMORY from `passwordEnc`, applied
30	 * via the DB client's STDIN (never an argv token — mirrors migrate-real.ts), and
31	 * then `passwordEnc` is CLEARED. Engine is installed on first use.
32	 *
33	 * SANDBOX / non-ENABLE_REAL_CPANEL: no SSH — status flips to ACTIVE and the
34	 * secret is scrubbed, exactly like the rest of the platform.
35	 */
36	
37	const REAL = !SANDBOX && process.env.ENABLE_REAL_CPANEL === "1";
38	
39	async function notify(userId: string, title: string, body?: string, href?: string) {
40	  try {
41	    await db.notification.create({ data: { userId, title, body, href } });
42	  } catch (e) {
43	    console.error("[cpanel/db] notify failed", e);
44	  }
45	}
46	
47	async function loadDb(job: Job) {
48	  const p = (job.payload ?? {}) as { databaseId?: string };
49	  if (!p.databaseId) throw new Error("db job: missing databaseId");
50	  const row = await db.vpsDatabase.findUnique({ where: { id: p.databaseId } });
51	  if (!row) throw new Error(`VpsDatabase ${p.databaseId} not found`);
52	  return row;
53	}
54	
55	async function sshServer(serverId: string): Promise<SftpServer> {
56	  const s = await db.server.findUnique({
57	    where: { id: serverId },
58	    select: {
59	      id: true,
60	      rootPassword: true,
61	      rootPasswordEnc: true,
62	      sshPort: true,
63	      dedicatedIp: { select: { address: true } },
64	    },
65	  });
66	  if (!s) throw new Error(`Server ${serverId} not found`);
67	  return s as SftpServer;
68	}
69	
70	export async function ensureMysql(conn: Client): Promise<void> {
71	  const have = await exec(conn, "command -v mysql >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
72	  if (have.stdout.trim() === "yes") return;
73	  const prefix = await pkgInstallPrefix(conn);
74	  const inst = await exec(conn, `${prefix} mariadb-server || ${prefix} default-mysql-server`, INSTALL_TIMEOUT_MS);
75	  if (inst.code !== 0) throw new Error(`MySQL/MariaDB install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
76	  await exec(conn, "systemctl enable --now mariadb 2>/dev/null || systemctl enable --now mysql", SETUP_TIMEOUT_MS);
77	}
78	
79	export async function ensurePostgres(conn: Client): Promise<void> {
80	  const have = await exec(conn, "command -v psql >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
81	  if (have.stdout.trim() === "yes") return;
82	  const prefix = await pkgInstallPrefix(conn);
83	  const inst = await exec(conn, `${prefix} postgresql`, INSTALL_TIMEOUT_MS);
84	  if (inst.code !== 0) throw new Error(`PostgreSQL install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
85	  await exec(conn, "systemctl enable --now postgresql", SETUP_TIMEOUT_MS);
86	}
87	
88	// ---------------------------------------------------------------------------
89	// Proving the credential works
90	// ---------------------------------------------------------------------------
91	//
92	// M7 #8: success here used to be "the CREATE statement exited 0 as root", and
93	// `passwordEnc` is nulled in the very same update that writes ACTIVE — so if the
94	// generated credential did not actually work, nobody could re-derive it, and the
95	// customer was handed a password that does not log in with a green ACTIVE pill
96	// beside it. `provisionDb` in worker/apps.ts already proves exactly this; the
97	// probes below are the same idea for both engines.
98	//
99	// The password never reaches argv. It is streamed over STDIN into a 0600 file
100	// written and deleted by the same shell — a defaults-extra-file for MySQL, a
101	// .pgpass for PostgreSQL — so it cannot appear in `ps`, in the shell history, or
102	// in an error message containing the command line.
103	
104	/** Log in AS the customer's MySQL user and run a trivial query. */
105	async function proveMysqlLogin(conn: Client, name: string, user: string, password: string): Promise<void> {
106	  const check = await execInput(
107	    conn,
108	    `umask 077; f=$(mktemp) && cat > "$f" && ` +
109	      `mysql --defaults-extra-file="$f" --protocol=socket -N -B -e 'SELECT 1' ${shellQuote(name)} >/dev/null 2>&1; ` +
110	      `rc=$?; rm -f "$f"; exit $rc`,
111	    `[client]\nuser=${user}\npassword=${password}\n`,
112	    SETUP_TIMEOUT_MS
113	  );
114	  if (check.code !== 0) {
115	    throw new Error(
116	      `the database was created but the generated credentials did not work when tested — ` +
117	        `not handing you a password that does not log in. Nothing usable was left behind; ` +
118	        `delete this database and create it again.`
119	    );
120	  }
121	}
122	
123	/**
124	 * Log in AS the customer's PostgreSQL role over TCP.
125	 *
126	 * TCP rather than the local socket on purpose: peer authentication on the unix
127	 * socket would succeed for the wrong reason (it authenticates the OS user, not
128	 * the password), which would make this probe prove nothing. `.pgpass` is
129	 * colon-and-backslash delimited, which is why assertInertSecret runs first.
130	 */
131	async function provePostgresLogin(conn: Client, name: string, user: string, password: string): Promise<void> {
132	  const check = await execInput(
133	    conn,
134	    `umask 077; f=$(mktemp) && cat > "$f" && ` +
135	      `PGPASSFILE="$f" psql -h 127.0.0.1 -U ${shellQuote(user)} -d ${shellQuote(name)} -tAc 'SELECT 1' >/dev/null 2>&1; ` +
136	      `rc=$?; rm -f "$f"; exit $rc`,
137	    `127.0.0.1:5432:${name}:${user}:${password}\n`,
138	    SETUP_TIMEOUT_MS
139	  );
140	  if (check.code !== 0) {
141	    throw new Error(
142	      `the database was created but the generated credentials did not work when tested over TCP — ` +
143	        `not handing you a password that does not log in. If your server's pg_hba.conf does not allow ` +
144	        `password auth on 127.0.0.1, fix that first; delete this database and create it again.`
145	    );
146	  }
147	}
