149	export async function dbCreate(job: Job): Promise<void> {
150	  const row = await loadDb(job);
151	  try {
152	    // Validate again before anything can reach a shell/SQL.
153	    assert(row.engine === "mysql" || row.engine === "postgres", `Unsupported engine: ${row.engine}`);
154	    assertIdent(row.name, "database name");
155	    assertIdent(row.dbUser, "database user");
156	
157	    // Simulation is a SANDBOX affordance and MUST NEVER run in production.
158	    // Copied from the guard at the end of `sslIssue` in worker/ssl.ts. Without
159	    // it, a production box that lost ENABLE_REAL_CPANEL flips the row to ACTIVE,
160	    // scrubs the password and tells the customer their database is ready —
161	    // having done nothing at all. `ENABLE_REAL_CPANEL=1` today, so this is
162	    // dormant; one lost .env line is all it takes.
163	    if (!REAL && !SANDBOX) {
164	      throw new Error(
165	        "Database provisioning is switched off on this server (ENABLE_REAL_CPANEL is not set), so no " +
166	          "database, user or password was created on your VM. Nothing exists — this database is NOT ready. " +
167	          "Ask support to enable real control-panel provisioning."
168	      );
169	    }
170	
171	    if (REAL) {
172	      const password = decryptSecret(row.passwordEnc);
173	      assert(password, "Generated password is missing or could not be decrypted.");
174	      assertInertSecret(password, "database password");
175	      const server = await sshServer(row.serverId);
176	      await withServerSsh(server, async (conn) => {
177	        if (row.engine === "mysql") {
178	          await ensureMysql(conn);
179	          // Root socket auth (Debian/Ubuntu default). Password only in the SQL
180	          // body, streamed via STDIN — never an argv token.
181	          const sql =
182	            `CREATE DATABASE IF NOT EXISTS \`${row.name}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;\n` +
183	            `CREATE USER IF NOT EXISTS '${row.dbUser}'@'localhost' IDENTIFIED BY '${password}';\n` +
184	            `ALTER USER '${row.dbUser}'@'localhost' IDENTIFIED BY '${password}';\n` +
185	            `GRANT ALL PRIVILEGES ON \`${row.name}\`.* TO '${row.dbUser}'@'localhost';\n` +
186	            `FLUSH PRIVILEGES;\n`;
187	          const r = await execInput(conn, "mysql --protocol=socket -uroot", sql, SETUP_TIMEOUT_MS);
188	          if (r.code !== 0) throw new Error(`MySQL create failed: ${why(r)}`);
189	          // The credential is about to become unrecoverable (passwordEnc is
190	          // nulled below), so prove it works while we still hold it.
191	          await proveMysqlLogin(conn, row.name, row.dbUser, password!);
192	        } else {
193	          await ensurePostgres(conn);
194	          // Run as the postgres superuser. Role password only in the SQL body via STDIN.
195	          const sql =
196	            `CREATE ROLE "${row.dbUser}" LOGIN PASSWORD '${password}';\n` +
197	            `CREATE DATABASE "${row.name}" OWNER "${row.dbUser}";\n` +
198	            `GRANT ALL PRIVILEGES ON DATABASE "${row.name}" TO "${row.dbUser}";\n`;
199	          const r = await execInput(conn, "sudo -u postgres psql -v ON_ERROR_STOP=1", sql, SETUP_TIMEOUT_MS);
200	          if (r.code !== 0) throw new Error(`PostgreSQL create failed: ${why(r)}`);
201	          await provePostgresLogin(conn, row.name, row.dbUser, password!);
202	        }
203	      });
204	    }
205	    // Scrub the transient secret regardless of path.
206	    await db.vpsDatabase.update({ where: { id: row.id }, data: { status: "ACTIVE", error: null, passwordEnc: null } });
207	    await notify(
208	      row.userId,
209	      `Database "${row.name}" is ready`,
210	      REAL
211	        ? `Your ${row.engine} database and user are provisioned, and we signed in with the generated password to confirm it works.`
212	        : `Simulated only (sandbox) — no VM was contacted and no database exists.`,
213	      `/dashboard/servers/${row.serverId}?tab=control panel`
214	    );
215	  } catch (e: any) {
216	    const reason = String(e?.message ?? e).slice(0, 400);
217	    // Even on failure, do not keep the secret around.
218	    await db.vpsDatabase.update({ where: { id: row.id }, data: { status: "FAILED", error: reason, passwordEnc: null } });
219	    await notify(row.userId, `Database "${row.name}" failed`, reason.slice(0, 200), `/dashboard/servers/${row.serverId}`);
220	  }
221	}
222	
223	/**
224	 * Drop the database and its user, and PROVE both are gone before the row is
225	 * deleted from our side.
226	 *
227	 * What this used to do: `await execInput(...)` — with the result DISCARDED, no
228	 * exit code checked, nothing read back — and then `db.vpsDatabase.delete()`
229	 * unconditionally. So when the DROP did not run (engine stopped, socket auth
230	 * broken, `sudo -u postgres` unavailable, the role still owning objects — which
231	 * makes `DROP ROLE` fail even with IF EXISTS) the panel reported the database
232	 * deleted while it and its GRANT ALL user were still live on the customer's VM,
233	 * now invisible and unmanageable. And because `@@unique([serverId, engine, name])`
234	 * frees the name, the next database created with the same name would be adopted
235	 * by `CREATE DATABASE IF NOT EXISTS` in `dbCreate` — handing a new, differently
236	 * scoped credential set onto the OLD data.
237	 *
238	 * The read-back is a query, not an exit code: `information_schema` / `pg_database`
239	 * are asked whether the objects still exist.
240	 */
241	export async function dbDelete(job: Job): Promise<void> {
242	  const row = await loadDb(job);
243	  try {
244	    assert(row.engine === "mysql" || row.engine === "postgres", `Unsupported engine: ${row.engine}`);
245	    assertIdent(row.name, "database name");
246	    assertIdent(row.dbUser, "database user");
247	    if (REAL) {
248	      const server = await sshServer(row.serverId);
249	      await withServerSsh(server, async (conn) => {
250	        if (row.engine === "mysql") {
251	          const sql =
252	            `DROP DATABASE IF EXISTS \`${row.name}\`;\n` +
253	            `DROP USER IF EXISTS '${row.dbUser}'@'localhost';\n` +
254	            `FLUSH PRIVILEGES;\n`;
255	          const r = await execInput(conn, "mysql --protocol=socket -uroot", sql, SETUP_TIMEOUT_MS);
256	          if (r.code !== 0) throw new Error(`MySQL drop failed, so nothing was removed: ${why(r)}`);
257	          const check = await execInput(
258	            conn,
259	            "mysql --protocol=socket -uroot -N -B",
260	            `SELECT COUNT(*) FROM information_schema.schemata WHERE schema_name = '${row.name}';\n` +
261	              `SELECT COUNT(*) FROM mysql.user WHERE user = '${row.dbUser}';\n`,
262	            SETUP_TIMEOUT_MS
263	          );
264	          assertDropped(row.engine, row.name, row.dbUser, check.code, check.stdout);
265	        } else {
266	          const sql =
267	            `DROP DATABASE IF EXISTS "${row.name}";\n` +
268	            `DROP ROLE IF EXISTS "${row.dbUser}";\n`;
269	          const r = await execInput(conn, "sudo -u postgres psql -v ON_ERROR_STOP=1", sql, SETUP_TIMEOUT_MS);
270	          if (r.code !== 0) throw new Error(`PostgreSQL drop failed, so nothing was removed: ${why(r)}`);
271	          const check = await execInput(
272	            conn,
273	            "sudo -u postgres psql -t -A -v ON_ERROR_STOP=1",
274	            `SELECT count(*) FROM pg_database WHERE datname = '${row.name}';\n` +
275	              `SELECT count(*) FROM pg_roles WHERE rolname = '${row.dbUser}';\n`,
276	            SETUP_TIMEOUT_MS
277	          );
278	          assertDropped(row.engine, row.name, row.dbUser, check.code, check.stdout);
279	        }
280	      });
281	    }
282	    await db.vpsDatabase.delete({ where: { id: row.id } });
283	  } catch (e: any) {
284	    const reason = String(e?.message ?? e).slice(0, 400);
285	    await db.vpsDatabase
286	      .update({ where: { id: row.id }, data: { status: "FAILED", error: reason } })
287	      .catch(() => {});
288	    await notify(
289	      row.userId,
290	      `Database "${row.name}" was NOT removed`,
291	      reason.slice(0, 200),
292	      `/dashboard/servers/${row.serverId}?tab=control panel`
293	    );
294	    // Failing the job puts this in Job.error and the admin job list. The DROPs
295	    // are `IF EXISTS`, so a retry is safe and idempotent.
296	    throw new Error(`database delete not verified: ${reason}`);
297	  }
298	}
299	
300	/**
301	 * Both count queries must answer 0. Anything else — including output we cannot
302	 * parse — means we do not know the objects are gone, and "we do not know" is not
303	 * "deleted".
304	 */
305	function assertDropped(
306	  engine: string,
307	  name: string,
308	  user: string,
309	  code: number | null,
310	  stdout: string
311	): void {
312	  const counts = String(stdout ?? "").trim().split(/\s+/);
313	  if (code !== 0 || counts.length < 2) {
314	    throw new Error(
315	      `could not confirm the ${engine} database "${name}" and user "${user}" were removed from the server ` +
316	        `(the check query exited ${code ?? "unknown"}). They may still exist — nothing has been deleted from ` +
317	        `your panel, so you can retry.`
318	    );
319	  }
320	  if (counts[0] !== "0") {
321	    throw new Error(
322	      `the ${engine} database "${name}" still exists on the server after the DROP, so it has NOT been ` +
323	        `removed. Nothing has been deleted from your panel.`
324	    );
325	  }
326	  if (counts[1] !== "0") {
327	    throw new Error(
328	      `the ${engine} database "${name}" was dropped but its user "${user}" still exists on the server — ` +
329	        `that account can still sign in, so this is not finished. Nothing has been deleted from your panel.`
330	    );
331	  }
332	}
