1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import { createHostingDatabase, listHostingDatabases, installDbTool, getHostingAccount, type HostingDbView } from "@/lib/actions-hosting";
5	
6	/** Database create/list UI for a hosting account. Extracted from the old
7	 *  HostingClient AccountCard; behaviour is identical, plus an access-gated
8	 *  Adminer database manager (install-then-open). */
9	export function DatabasesPanel({ accountId, username, maxDatabases, primaryDomain, dbToolPath }: { accountId: string; username: string; maxDatabases: number; primaryDomain: string; dbToolPath: string | null }) {
10	  const [dbs, setDbs] = useState<HostingDbView[]>([]);
11	  const [dbLabel, setDbLabel] = useState("");
12	  const [dbBusy, setDbBusy] = useState(false);
13	  const [dbErr, setDbErr] = useState("");
14	  const [newDbPassword, setNewDbPassword] = useState<{ name: string; password: string } | null>(null);
15	  const [toolPath, setToolPath] = useState<string | null>(dbToolPath);
16	  const [toolBusy, setToolBusy] = useState(false);
17	  const [toolErr, setToolErr] = useState("");
18	
19	  useEffect(() => { listHostingDatabases(accountId).then(setDbs).catch(() => {}); }, [accountId]);
20	
21	  /** Open the Adminer DB manager, installing it first if needed. The customer logs
22	   *  in with their own scoped DB user (shown when they create a database above). */
23	  async function openDbManager() {
24	    if (toolPath) { window.open(`https://${primaryDomain}${toolPath}`, "_blank", "noopener"); return; }
25	    setToolBusy(true); setToolErr("");
26	    const res = await installDbTool(accountId);
27	    if (res.error) { setToolErr(res.error); setToolBusy(false); return; }
28	    if (res.url) { setToolPath(res.url); setToolBusy(false); window.open(`https://${primaryDomain}${res.url}`, "_blank", "noopener"); return; }
29	    // Queued — poll the account until the worker drops Adminer + records its path.
30	    let tries = 0;
31	    const poll = setInterval(() => {
32	      tries++;
33	      getHostingAccount(accountId).then((fresh) => {
34	        if (fresh?.dbToolPath) {
35	          clearInterval(poll); setToolPath(fresh.dbToolPath); setToolBusy(false);
36	          window.open(`https://${primaryDomain}${fresh.dbToolPath}`, "_blank", "noopener");
37	        }
38	      }).catch(() => {});
39	      if (tries >= 15) { clearInterval(poll); setToolBusy(false); setToolErr("Still setting up the database manager — try again in a moment."); }
40	    }, 3000);
41	  }
42	
43	  async function addDb() {
44	    if (!dbLabel.trim()) return;
45	    setDbBusy(true);
46	    setDbErr("");
47	    try {
48	      const res = await createHostingDatabase(accountId, dbLabel.trim());
49	      if (res.error) setDbErr(res.error);
50	      else {
51	        setNewDbPassword({ name: `${username}_${dbLabel.trim().toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db"}`, password: res.password ?? "" });
52	        setDbLabel("");
53	        listHostingDatabases(accountId).then(setDbs).catch(() => {});
54	      }
55	    } finally {
56	      setDbBusy(false);
57	    }
58	  }
59	
60	  if (maxDatabases <= 0) {
61	    return <p className="text-sm text-slate-400">Databases aren’t included on this plan. Upgrade to add MySQL databases.</p>;
62	  }
63	
64	  return (
65	    <div className="space-y-4">
66	      <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2">
67	        <div className="mb-1 flex items-center justify-between">
68	          <p className="text-sm font-medium text-slate-300">
69	            Databases <span className="text-xs text-slate-500">({dbs.length}/{maxDatabases})</span>
70	          </p>
71	          <button
72	            type="button"
73	            onClick={openDbManager}
74	            disabled={toolBusy}
75	            title="Manage your databases in the browser (log in with your database user)"
76	            className="rounded-lg border border-white/10 bg-white/[0.03] px-2.5 py-1 text-xs text-brand-200 hover:bg-white/[0.06] disabled:cursor-wait disabled:text-slate-500"
77	          >
78	            {toolBusy ? "Setting up…" : "Open database manager"}
79	          </button>
80	        </div>
81	        {toolErr && <p className="mb-1 text-xs text-amber-300">{toolErr}</p>}
82	        <p className="mb-1 text-[11px] text-slate-500">
83	          Log in with a <span className="text-slate-400">database user</span> you created above (host <span className="font-mono text-slate-400">localhost</span>) — it only ever sees your own databases.
84	        </p>
85	        {dbs.length > 0 && (
86	          <ul className="mb-2 space-y-0.5 text-xs">
87	            {dbs.map((d) => (
88	              <li key={d.id} className="flex items-center gap-2 text-slate-400">
89	                <span className="font-mono text-slate-200">{d.name}</span>
90	                <span className="text-slate-500">user {d.dbUser}</span>
91	                <span className={d.status === "ACTIVE" ? "text-emerald-300" : "text-amber-300"}>{d.status.toLowerCase()}</span>
92	              </li>
93	            ))}
94	          </ul>
95	        )}
96	        {newDbPassword && (
97	          <div className="mb-2 rounded border border-emerald-500/30 bg-emerald-500/10 px-2 py-1.5 text-xs text-emerald-200">
98	            Created <span className="font-mono">{newDbPassword.name}</span> — password (shown once):{" "}
99	            <span className="font-mono">{newDbPassword.password}</span>
100	          </div>
101	        )}
102	        {dbs.length < maxDatabases ? (
103	          <div className="flex items-center gap-2">
104	            <input className="input flex-1 text-xs" placeholder="database name" value={dbLabel} onChange={(e) => setDbLabel(e.target.value)} />
105	            <button className="btn-secondary text-xs" disabled={dbBusy || !dbLabel.trim()} onClick={addDb}>{dbBusy ? "…" : "Create"}</button>
106	          </div>
107	        ) : (
108	          <p className="text-xs text-slate-500">You’ve used all the databases on your plan.</p>
109	        )}
110	        {dbErr && <p className="mt-1 text-xs text-amber-300">{dbErr}</p>}
111	      </div>
112	    </div>
113	  );
114	}
