91	/**
92	 * Inode (file-count) quota for `setquota`, the containment for a DoS the block
93	 * quota alone doesn't stop: a tenant creating MILLIONS of tiny files exhausts the
94	 * shared filesystem's inode table — filling no disk blocks but breaking every
95	 * neighbour's ability to create a file. `setquota … <isoft> <ihard>` of `0 0`
96	 * means UNLIMITED inodes, so a real cap is required here. Scales gently off the
97	 * plan's disk size but is floored (a 1 GB plan still gets working room) and
98	 * ceilinged (a huge plan can't effectively uncap); hard carries 25% headroom
99	 * over soft so a tenant hits the soft warning before the hard wall.
100	 */
101	export function diskQuotaInodes(diskGB: number): { soft: number; hard: number } {
102	  const gb = Math.max(1, Math.floor(diskGB || 1));
103	  const soft = Math.min(2_000_000, Math.max(200_000, gb * 50_000));
104	  const hard = Math.floor(soft * 1.25);
105	  return { soft, hard };
106	}
