317	/**
318	 * Escape a MySQL identifier for the `ON <db>.*` clause of a GRANT.
319	 *
320	 * In GRANT, `_` and `%` are LIKE-wildcards: an un-escaped grant on `nxuser_wp`
321	 * silently also grants on `nxuserXwp`, `nxuser_wpZ`, … i.e. a neighbouring
322	 * tenant's database. Escaping them (and the escape char itself) with a
323	 * backslash pins the grant to exactly one database.
324	 */
325	export function escapeGrantDbName(name: string): string {
326	  return name.replace(/([\\_%])/g, "\\$1");
327	}
328	
329	/**
330	 * The scoped SQL that creates one account database + user and grants that user
331	 * privileges on THAT DATABASE ONLY.
332	 *
333	 * Security invariants (audited): the GRANT is pinned to the exact db via
334	 * escapeGrantDbName (no wildcard bleed into a peer's db), it is NEVER `*.*`,
335	 * and `ALL PRIVILEGES` at database scope confers no global FILE/SUPER (those
336	 * are server-level and cannot be granted by a db-scoped GRANT). Returns plain
337	 * SQL with real backticks; the caller shell-escapes for `mysql -e`.
338	 */
339	export function buildScopedGrantSql(dbName: string, dbUser: string, dbPass: string): string {
340	  const grantName = escapeGrantDbName(dbName);
341	  return (
342	    `CREATE DATABASE IF NOT EXISTS \`${dbName}\`; ` +
343	    `CREATE USER IF NOT EXISTS '${dbUser}'@'localhost' IDENTIFIED BY '${dbPass}'; ` +
344	    `GRANT ALL PRIVILEGES ON \`${grantName}\`.* TO '${dbUser}'@'localhost'; ` +
345	    `FLUSH PRIVILEGES;`
346	  );
347	}
