934	async function taskAppInstall(conn: Client, a: { id: string; username: string; primaryDomain: string; maxDatabases: number }, payload: string | null): Promise<string> {
935	  const p = JSON.parse(payload || "{}") as { slug?: string; dbName?: string; dbUser?: string; dbPassEnc?: string };
936	  const slug = String(p.slug ?? "");
937	  const recipe = APP_RECIPES[slug];
938	  if (!recipe) throw new Error("unknown app");
939	  if (recipe.needsDb) await assertDbCap(a.id, a.maxDatabases);
940	  const u = a.username;
941	  if (!isValidUnixUsername(u)) throw new Error("unsafe account");
942	  const { webroot } = accountPaths(u);
943	  const isBz2 = recipe.url.endsWith(".bz2");
944	  const tarFlags = `${isBz2 ? "xjf" : "xzf"} - ${recipe.strip ? `--strip-components=${recipe.strip}` : ""}`;
945	  // Download + extract into the webroot AS the account user (jailed).
946	  await run(conn, `download ${slug}`, `sudo -u ${u} -H bash -c "cd ${webroot} && curl -fsSL '${recipe.url}' | tar ${tarFlags}"`);
947	  let dbInfo = "";
948	  if (recipe.needsDb) {
949	    const dbName = String(p.dbName ?? "");
950	    const dbUser = String(p.dbUser ?? "");
951	    const dbPass = (p.dbPassEnc ? decryptSecret(p.dbPassEnc) : "") ?? "";
952	    if (!/^[a-z0-9_]{1,64}$/.test(dbName) || !/^[a-z0-9_]{1,32}$/.test(dbUser) || !dbPass) throw new Error("invalid db identifiers");
953	    const sql = sqlForMysqlExec(buildScopedGrantSql(dbName, dbUser, dbPass));
954	    await run(conn, "app db", `mysql -e "${sql}"`);
955	    await db.hostingDatabase.create({ data: { accountId: a.id, name: dbName, dbUser, passwordEnc: null, status: "ACTIVE" } }).catch(() => undefined);
956	    dbInfo = ` Database: ${dbName} · user ${dbUser} · password ${dbPass} (host localhost).`;
957	  }
958	  return JSON.stringify({ app: recipe.name, url: `https://${a.primaryDomain}/`, note: recipe.note + dbInfo });
959	}

