961	/** Archive the account's home + DB dumps to a node-local backups dir.
962	 *
963	 * SECURITY (audit 2026-08-01, cross-tenant DB compromise): the DB dumps are
964	 * written to a ROOT-ONLY directory OUTSIDE the tenant's chroot and are NEVER
965	 * chowned to the tenant. The old code dumped into ${home}/.dbdump and chowned it
966	 * to the account user, so the tenant — who holds live SFTP creds chrooted to
967	 * ${home} — could race in and overwrite <db>.sql with arbitrary SQL that restore
968	 * later piped into `mysql` as root (a shared-node-wide GRANT/USE). Keeping the
969	 * dumps root-owned and off the tenant tree means the archived SQL is always our
970	 * own mysqldump output, never tenant-controlled. */
971	async function taskBackup(conn: Client, a: { id: string; username: string }, tsLabel: string): Promise<void> {
972	  const u = a.username;
973	  const dir = `/var/hosting-backups/${u}`;
974	  const dumpDir = `${dir}/dbdump`;
975	  const path = `${dir}/${tsLabel}.tar.gz`;
976	  // Root-only staging for the DB dumps; the whole dir is 700 root:root so the
977	  // tenant can neither read nor tamper with it.
978	  await run(
979	    conn,
980	    "dump dbs",
981	    `rm -rf ${dumpDir}; mkdir -p ${dumpDir}; chown -R root:root ${dir}; chmod 700 ${dir} ${dumpDir}; ` +
982	      `for dbn in $(mysql -N -e "SHOW DATABASES LIKE '${u}\\_%'" 2>/dev/null); do mysqldump "$dbn" > ${dumpDir}/"$dbn".sql 2>/dev/null; done`,
983	  );
984	  // One archive holding the home tree (${u}/…) and the root-owned dumps (dbdump/…).
985	  await run(conn, "tar home", `tar -czf ${path} -C /home ${u} -C ${dir} dbdump && rm -rf ${dumpDir}`);
986	  const st = await exec(conn, `stat -c %s ${path} 2>/dev/null || echo 0`);
987	  const sizeBytes = Math.max(0, Math.min(2_000_000_000, Number(st.out.trim()) || 0));
988	  await db.hostingBackup.create({ data: { accountId: a.id, path, sizeBytes } });
989	  // Retain the newest 5 per account; delete older files + rows.

